    Exercise(
        id="ex_sql_dg2_west_drop",
        title="Localise the revenue drop",
        module="diagnostic", language="sql", difficulty="Intermediate", topic="Drill-down by segment",
        competencies=["segmentation_rca"], lesson="dg2",
        business_question="Which region x category combinations lost the most revenue in Aug-Sep 2024 versus Aug-Sep 2023?",
        dataset="retail", tables=["retail.orders", "retail.order_items", "retail.products", "retail.categories"], search_path="retail",
        requirements=[
            "Completed orders in August or September of 2023 and 2024.",
            "Columns: `region`, `category_name`, `rev_2023`, `rev_2024`, `change` (rev_2024 - rev_2023); all rounded to 2 decimals.",
            "Return the 5 rows with the most negative change, most negative first.",
        ],
        expected_output="5 rows ordered by change ascending.",
        starter_code="WITH rev AS (\n    SELECT o.region, c.category_name, YEAR(o.order_date) AS yr,\n           SUM(oi.quantity * oi.unit_price * (1 - COALESCE(oi.discount_pct, 0))) AS revenue\n    FROM orders o\n    JOIN order_items oi ON oi.order_id = o.order_id\n    JOIN products p ON p.product_id = oi.product_id\n    JOIN categories c ON c.category_id = p.category_id\n    WHERE o.status = 'Completed' AND MONTH(o.order_date) IN (8, 9)\n    GROUP BY 1, 2, 3\n)\nSELECT * FROM rev;\n",
        solution="WITH rev AS (\n    SELECT o.region, c.category_name, YEAR(o.order_date) AS yr,\n           SUM(oi.quantity * oi.unit_price * (1 - COALESCE(oi.discount_pct, 0))) AS revenue\n    FROM orders o\n    JOIN order_items oi ON oi.order_id = o.order_id\n    JOIN products p ON p.product_id = oi.product_id\n    JOIN categories c ON c.category_id = p.category_id\n    WHERE o.status = 'Completed' AND MONTH(o.order_date) IN (8, 9)\n    GROUP BY 1, 2, 3\n), wide AS (\n    SELECT region, category_name,\n           SUM(CASE WHEN yr = 2023 THEN revenue ELSE 0 END) AS rev_2023,\n           SUM(CASE WHEN yr = 2024 THEN revenue ELSE 0 END) AS rev_2024\n    FROM rev GROUP BY 1, 2\n)\nSELECT region, category_name, ROUND(rev_2023, 2) AS rev_2023, ROUND(rev_2024, 2) AS rev_2024,\n       ROUND(rev_2024 - rev_2023, 2) AS change\nFROM wide\nORDER BY change\nLIMIT 5;",
        explanation="Pivoting years into columns with conditional aggregation makes the comparison explicit. West Electronics dominates the decline - far larger than any other combination - which localises the problem.",
        hints=["Use SUM(CASE WHEN yr = 2023 THEN revenue ELSE 0 END) to pivot years into columns.", "Sort by change ascending to see the biggest losses first."],
        order_matters=True, rubric=SQL_RUBRIC,
    ),
    Exercise(
        id="ex_py_dg2_mix_rate",
        title="Mix vs rate: why did gross margin move?",
        module="diagnostic", language="python", difficulty="Advanced", topic="Mix/rate decomposition",
        competencies=["segmentation_rca", "causal_reasoning"], lesson="dg2", kind="challenge",
        business_question="Gross margin % changed between 2023 and 2024. Was it because category margins changed (rate) or because the category mix shifted (mix)?",
        dataset="retail", tables=["retail.orders", "retail.order_items", "retail.products", "retail.categories"],
        preload={"orders": "retail.orders", "items": "retail.order_items", "products": "retail.products"},
        requirements=[
            "Completed orders only. revenue = quantity*unit_price*(1-discount, NULL->0); cost = quantity*products.unit_cost.",
            "Per category_id and year: `share` = category revenue / year revenue, `margin` = (revenue - cost) / revenue.",
            "`total_change` = overall margin 2024 - overall margin 2023 (as fractions).",
            "`rate_effect` = sum over categories of share_2023 * (margin_2024 - margin_2023).",
            "`mix_effect` = sum over categories of (share_2024 - share_2023) * margin_2024. rate_effect + mix_effect must equal total_change.",
        ],
        expected_output="Three floats: total_change, rate_effect, mix_effect.",
        starter_code="df = items.merge(orders[['order_id', 'status', 'order_date']], on='order_id')\ndf = df.merge(products[['product_id', 'category_id', 'unit_cost']], on='product_id')\n\ntotal_change = None\nrate_effect = None\nmix_effect = None\n",
        solution="df = items.merge(orders[['order_id', 'status', 'order_date']], on='order_id')\ndf = df.merge(products[['product_id', 'category_id', 'unit_cost']], on='product_id')\ndf = df[df['status'] == 'Completed'].copy()\ndf['year'] = df['order_date'].dt.year\ndf['revenue'] = df['quantity'] * df['unit_price'] * (1 - df['discount_pct'].fillna(0))\ndf['cost'] = df['quantity'] * df['unit_cost']\ng = df.groupby(['year', 'category_id'])[['revenue', 'cost']].sum()\ng['share'] = g['revenue'] / g.groupby(level='year')['revenue'].transform('sum')\ng['margin'] = (g['revenue'] - g['cost']) / g['revenue']\ns = g['share'].unstack(level='year')\nm = g['margin'].unstack(level='year')\ntot = df.groupby('year')[['revenue', 'cost']].sum()\noverall = (tot['revenue'] - tot['cost']) / tot['revenue']\ntotal_change = overall[2024] - overall[2023]\nrate_effect = (s[2023] * (m[2024] - m[2023])).sum()\nmix_effect = ((s[2024] - s[2023]) * m[2024]).sum()\n",
        explanation="Overall margin is a revenue-weighted average of category margins. Holding the 2023 mix fixed isolates the rate effect; the remainder is the mix effect. The two add up exactly to the total change, which is a useful self-check.",
        hints=["Group by ['year', 'category_id'] and sum revenue and cost.", "share = revenue / revenue total for that year (groupby(level='year').transform('sum')).", "Unstack year into columns to subtract 2024 - 2023 per category."],
        checks=[
            Check("total_change", "assert close(need('total_change'), ref['total_change'], tol=1e-6), 'total_change should be overall margin 2024 minus 2023, as fractions (e.g. -0.002).'"),
            Check("rate_effect", "assert close(need('rate_effect'), ref['rate_effect'], tol=1e-6), 'rate_effect = sum(share_2023 * (margin_2024 - margin_2023)).'", weight=2),
            Check("mix_effect", "assert close(need('mix_effect'), ref['mix_effect'], tol=1e-6), 'mix_effect = sum((share_2024 - share_2023) * margin_2024).'", weight=2),
            Check("effects add up", "assert close(float(need('rate_effect')) + float(need('mix_effect')), float(need('total_change')), tol=1e-9), 'rate_effect + mix_effect should equal total_change exactly.'"),
        ],
        visible_tests=["Three effects match the reference", "Effects sum to the total change"],
        rubric=[("Correct category shares and margins", 40), ("Correct decomposition", 40), ("Self-consistency", 20)],
    ),
