        solution="d = cf.dropna(subset=['logins_first_month'])\npearson = d['logins_first_month'].corr(d['churned_6m'])\nspearman = d['logins_first_month'].corr(d['churned_6m'], method='spearman')\nd = d.assign(q=pd.qcut(d['logins_first_month'], 4, labels=['Q1', 'Q2', 'Q3', 'Q4']))\nchurn_by_quartile = d.groupby('q', observed=True)['churned_6m'].mean()\n",
