    Exercise(
        id="ex_py_dg6_anomaly",
        title="Rolling z-score anomaly detector",
        module="diagnostic", language="python", difficulty="Professional", topic="Anomaly detection",
        competencies=["segmentation_rca", "statistical_inference"], lesson="dg6",
        business_question="Build the first version of a daily demand alert.",
        dataset="operations", tables=["operations.daily_demand"], preload={"dd": "operations.daily_demand"},
        requirements=[
            "`daily`: total units_demanded per date (Series sorted by date).",
            "`z`: rolling z-score using the **previous** 28 days only (mean and std of daily.shift(1), window 28, min_periods 28).",
            "`anomalies`: the dates where |z| > 3; `n_anomalies`: how many.",
        ],
        expected_output="Two Series and a count.",
        starter_code="daily = dd.groupby('date')['units_demanded'].sum().sort_index()\nz = None\nanomalies = None\nn_anomalies = None\n",
        solution="daily = dd.groupby('date')['units_demanded'].sum().sort_index()\nroll = daily.shift(1).rolling(28, min_periods=28)\nz = (daily - roll.mean()) / roll.std()\nanomalies = z[z.abs() > 3]\nn_anomalies = int(len(anomalies))\n",
        explanation="Shifting by one day before rolling prevents each day from influencing its own baseline. Expect several flags around seasonal turning points - a sign that a weekday-aware baseline would reduce false alarms.",
        hints=["daily.shift(1).rolling(28, min_periods=28) builds a trailing window.", "z = (value - mean) / std.", "Filter with z.abs() > 3."],
        checks=[
            Check("daily", "d = need('daily', pd.Series)\nassert len(d) == len(ref['daily']) and np.allclose(d.values, ref['daily'].values), 'daily should be total demand per date.'"),
            Check("z uses a trailing window", "zz = need('z', pd.Series)\nassert np.allclose(zz.values.astype(float), ref['z'].values, equal_nan=True, atol=1e-9), 'z-scores differ. Did you shift(1) so the current day is excluded from its own baseline, and use min_periods=28?'", weight=2),
            Check("n_anomalies", "assert int(need('n_anomalies')) == ref['n_anomalies'], f'Expected a different number of anomalies (threshold |z| > 3).'"),
        ],
        visible_tests=["daily totals correct", "z-scores computed from a trailing window", "anomaly count matches"],
        rubric=[("Correct aggregation", 20), ("Leak-free baseline", 50), ("Correct flags", 30)],
    ),
